<script setup>
import {computed,ref,watch} from 'vue'
import {count} from '../dataModel.js'
const props=defineProps({fans:{type:Array,default:()=>[]},compact:Boolean,supported:{type:Boolean,default:true},initial:{type:String,default:'bars'}})
const mode=ref(props.initial),query=ref(''),showAll=ref(false),hideZero=ref(true),selected=ref(null)
watch(()=>props.initial,v=>mode.value=v)
watch(()=>props.fans,()=>selected.value=null)
const filtered=computed(()=>props.fans.filter(f=>(!hideZero.value||f.value>0)&&f.label.includes(query.value.trim())))
const visible=computed(()=>showAll.value?filtered.value:filtered.value.slice(0,props.compact?6:12))
const max=computed(()=>Math.max(1,...props.fans.map(f=>f.value)))
</script>
<template><section class="panel fan-panel"><div class="panel-heading"><div><h2>番种观察</h2><span class="subtle">出现频次 · 累计口径</span></div><div class="segmented" aria-label="番种展示方式"><button v-for="item in [['bars','条形'],['matrix','矩阵'],['table','表格']]" :key="item[0]" :class="{active:mode===item[0]}" :aria-pressed="mode===item[0]" @click="mode=item[0]">{{item[1]}}</button></div></div><div v-if="!supported" class="inline-empty">当前规则暂不提供番种统计，可查看对局与基础数据。</div><template v-else><div class="fan-toolbar" v-if="!compact"><input v-model="query" type="search" placeholder="查找番种" aria-label="查找番种"><label class="check-label"><input v-model="hideZero" type="checkbox">仅有记录</label><span class="subtle">{{filtered.length}} 项</span></div><div v-if="!visible.length" class="inline-empty">当前范围内暂无匹配番种</div><div v-else-if="mode==='bars'" class="fan-bars"><button v-for="fan in visible" :key="fan.key" :class="{active:selected?.key===fan.key}" @click="selected=fan"><span>{{fan.label}}</span><span class="fan-track"><i :style="{width:(fan.value/max*100)+'%'}"/></span><strong>{{count(fan.value)}}</strong><small>{{fan.share}}</small></button></div><div v-else-if="mode==='matrix'" class="fan-matrix"><button v-for="fan in visible" :key="fan.key" :class="{active:selected?.key===fan.key}" :style="{'--intensity':Math.sqrt(fan.value/max)}" @click="selected=fan"><span>{{fan.label}}</span><strong>{{count(fan.value)}}</strong><small>{{fan.share}}</small></button></div><div v-else class="table-scroll"><table><thead><tr><th>番种</th><th class="numeric">出现次数</th><th class="numeric">占和牌次数</th></tr></thead><tbody><tr v-for="fan in visible" :key="fan.key"><td>{{fan.label}}</td><td class="numeric">{{count(fan.value)}}</td><td class="numeric">{{fan.share}}</td></tr></tbody></table></div><div v-if="selected" class="selection-note"><strong>{{selected.label}}</strong> 累计出现 {{count(selected.value)}} 次，占和牌次数 {{selected.share}}。<button class="text-button" @click="selected=null" aria-label="收起番种详情">收起</button></div><button v-if="filtered.length>(compact?6:12)" class="expand-button" @click="showAll=!showAll">{{showAll?'收起':'查看全部 '+filtered.length+' 个番种'}} <span>{{showAll?'−':'+'}}</span></button><p class="panel-footnote">以和牌次数为分母；花牌等可重复计数，单项及合计均可能超过 100%。</p></template></section></template>
